Remove the MATCH_FLAG_DIFF_ENCODE condition to validate all DEFAULT_TABLE
entries unconditionally.

Fixes: 031dcc8f4e84 ("apparmor: dfa add support for state differential encoding")
Reported-by: Qualys Security Advisory <qsa@qualys.com>
Tested-by: Salvatore Bonaccorso <carnil@debian.org>
Reviewed-by: Georgia Garcia <georgia.garcia@canonical.com>
Reviewed-by: Cengiz Can <cengiz.can@canonical.com>
Signed-off-by: Massimiliano Pellizzer <massimiliano.pellizzer@canonical.com>
Signed-off-by: John Johansen <john.johansen@canonical.com>

Here is the root cause:
The verify_dfa() function in match.c only validated the bounds of DEFAULT_TABLE entries when the state was not differentially encoded (i.e., when MATCH_FLAG_DIFF_ENCODE was not set). During the verification loop, when traversing the differential encoding chain, the code reads DEFAULT_TABLE[j] and uses it as an array index without any bounds check. A malformed DFA with DEFAULT_TABLE[j] >= state_count causes out-of-bounds reads and writes, leading to a slab-out-of-bounds vulnerability.

Here is the patch:
  */
 static int verify_dfa(struct aa_dfa *dfa)
 {
 	size_t i, state_count, trans_count;
 	int error = -EPROTO;

 	state_count = dfa->tables[YYTD_ID_BASE]->td_lolen;
 	trans_count = dfa->tables[YYTD_ID_NXT]->td_lolen;
 	if (state_count == 0)
 		goto out;
 	for (i = 0; i < state_count; i++) {
-		if (!(BASE_TABLE(dfa)[i] & MATCH_FLAG_DIFF_ENCODE) &&
-		    (DEFAULT_TABLE(dfa)[i] >= state_count))
+		if (DEFAULT_TABLE(dfa)[i] >= state_count) {
+			pr_err("AppArmor DFA default state out of bounds");
 			goto out;
+		}
 		if (BASE_TABLE(dfa)[i] & MATCH_FLAGS_INVALID) {
 			pr_err("AppArmor DFA state with invalid match flags");
 			goto out;
 		}
 		if ((BASE_TABLE(dfa)[i] & MATCH_FLAG_DIFF_ENCODE)) {
 			if (!(dfa->flags & YYTH_FLAG_DIFF_ENCODE)) {
 				pr_err("AppArmor DFA diff encoded transition state without header flag");
 				goto out;
 			}
 		}
 		if ((BASE_TABLE(dfa)[i] & MATCH_FLAG_OOB_TRANSITION)) {
 			if (base_idx(BASE_TABLE(dfa)[i]) < dfa->max_oob) {
 				pr_err("AppArmor DFA out of bad transition out of range");
 				goto out;
 			}
 			if (!(dfa->flags & YYTH_FLAG_OOB_TRANS)) {
 				pr_err("AppArmor DFA out of bad transition state without header flag");
 				goto out;
 			}
 		}
 		if (base_idx(BASE_TABLE(dfa)[i]) + 255 >= trans_count) {
 			pr_err("AppArmor DFA next/check upper bounds error\n");
 			goto out;
 		}
 	}

 	for (i = 0; i < trans_count; i++) {
 		if (NEXT_TABLE(dfa)[i] >= state_count)
 			goto out;
 		if (CHECK_TABLE(dfa)[i] >= state_count)
 			goto out;
 	}

 	/* Now that all the other tables are verified, verify diffencoding */
 	for (i = 0; i < state_count; i++) {
 		size_t j, k;

 		for (j = i;
 		     (BASE_TABLE(dfa)[j] & MATCH_FLAG_DIFF_ENCODE) &&
 		     !(BASE_TABLE(dfa)[j] & MARK_DIFF_ENCODE);
 		     j = k) {
 			k = DEFAULT_TABLE(dfa)[j];
 			if (j == k)
 				goto out;
 			if (k < j)
 				break;		/* already verified */
 			BASE_TABLE(dfa)[j] |= MARK_DIFF_ENCODE;
 		}
 	}
 	error = 0;

 out:
 	return error;
 }



